const sanitizeEmailProperties = (contacts: VCardContact[]): VCardContact[] => {
    return contacts.map((contact) => {
        if (!contact.email) {
            return contact;
        }

        const existingGroups = contact.email.map(({ group }) => group).filter(isTruthy);

        return {
            ...contact,
            email: contact.email
                .flatMap((property) => {
                    if (!Array.isArray(property.value)) {
